    [4084] = {n="Silver Heart", d="Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", tgo={{"Angerclaw Bear", "Angerclaw Grizzly", "Angerclaw Mauler", "Felpaw Wolf", "Felpaw Scavenger", "Felpaw Ravager", "Death Howl", "Mongress"}, {"Irontree Wanderer", "Irontree Stomper"}}},
    [4101] = {n="Cleansing Felwood", d="Bring 15 Blood Amber to Arathandris Silversky in Felwood.", tgo={{"Warpwood Moss Flayer", "Warpwood Shredder", "Dessecus"}}},
    [4123] = {n="The Heart of the Mountain", d="Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", objs={"Heart of the Mountain"}},
    [4124] = {n="The Missing Courier", d="Speak with Ginro Hearthkindle in Feathermoon Stronghold."},
    [4125] = {n="The Missing Courier", d="Locate the courier's boat somewhere along the coast of Feralas."},
    [4126] = {n="Hurley Blackbreath", d="Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", tgo={{"Hurley Blackbreath", "Blackbreath Crony"}}},
    [4127] = {n="Boat Wreckage", d="Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found."},
    [4128] = {n="Ragnar Thunderbrew", d="Speak with Ragnar Thunderbrew."},
    [4129] = {n="The Knife Revealed", d="Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold."},
    [4130] = {n="Psychometric Reading", d="Speak with Ginro Hearthkindle in Feathermoon Stronghold."},
    [4131] = {n="The Woodpaw Gnolls", d="Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself."},
    [4135] = {n="The Writhing Deep", d="Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep. According to the note, it is located to the south of the Woodpaw gnoll camps."},
    [4141] = {n="Muigin and Larion", d="Collect 15 Bloodpetals and return to Muigin.", tgo={{"Bloodpetal Lasher", "Bloodpetal Flayer", "Bloodpetal Thresher", "Bloodpetal Trapper"}}},
    [4142] = {n="A Visit to Gregan", d="Take a Bloodpetal to Gregan Brewspewer in Feralas."},
    [4161] = {n="Recipe of the Kaldorei", d="Collect 7 Small Spider Legs for Zarrin in Dolanaar.", tgo={{"Forest Spider", "Mine Spider", "Mother Fang", "Cliff Lurker", "Wood Lurker", "Forest Lurker", "Vicious Night Web Spider", "Moss Stalker"}}},
    [4182] = {n="Dragonkin Menace", d="Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", tgo={{"Black Broodling"}, {"Black Dragonspawn"}, {"Black Drake"}, {"Black Wyrmkin"}}},
    [4183] = {n="The True Masters", d="Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."},
    [4184] = {n="The True Masters", d="Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\nBolvar resides in Stormwind Keep."},
    [4185] = {n="The True Masters", d="Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", tgo={{"Lady Katrana Prestor"}}},
    [4186] = {n="The True Masters", d="Take Bolvar's Decree to Magistrate Solomon in Lakeshire."},
    [4223] = {n="The True Masters", d="Speak with Marshal Maxwell in the Burning Steppes."},
    [4224] = {n="The True Masters", d="Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\nYou recall Marshal Maxwell telling you to search for him in a cave to the north.", tgo={{"Ragged John"}}},
    [4241] = {n="Marshal Windsor", d="Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\nYou recall Ragged John talking about Windsor being dragged off to a prison."},
    [4243] = {n="Chasing A-Me 01", d="Find A-Me 01 in Un'Goro Crater."},
    [4244] = {n="Chasing A-Me 01", d="Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", tgo={{"Clunk", "Frostwolf Shredder Unit", "Stormpike Shredder Unit", "7:XT"}}},
    [4245] = {n="Chasing A-Me 01", d="Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater."},
    [4262] = {n="Overmaster Pyron", d="Slay Overmaster Pyron and return to Jalinda Sprig.\nYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", tgo={{"Overmaster Pyron"}}},
    [4265] = {n="Freed from the Hive", d="Free Raschal from the Zukk'ash hive.\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well."},
    [4266] = {n="A Hero's Welcome", d="Speak with Shandris Feathermoon in Feathermoon Stronghold."},
    [4267] = {n="Rise of the Silithid", d="Bring Raschal's Report to Gracina Spiritmight in Darnassus."},
    [4283] = {n="FIFTY! YEP!", d="Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes.", tgo={{"Blackrock Soldier", "Blackrock Sorcerer", "Blackrock Slayer", "Blackrock Warlock", "Blackrock Battlemaster", "Blackrock Worg", "Ember Worg", "Slavering Ember Worg"}}},
    [4284] = {n="Crystals of Power", d="Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", objs={"Red Power Crystal", "Yellow Power Crystal", "Green Power Crystal", "Blue Power Crystal"}},
    [4285] = {n="The Northern Pylon", d="Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", objs={"Northern Crystal Pylon"}},
    [4286] = {n="The Good Stuff", d="Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", tgo={{"Anvilrage Overseer", "Anvilrage Warden", "Anvilrage Guardsman", "Anvilrage Footman", "Anvilrage Soldier", "Anvilrage Medic", "Anvilrage Officer", "Shadowforge Peasant"}}},
    [4287] = {n="The Eastern Pylon", d="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.", objs={"Eastern Crystal Pylon"}},
    [4288] = {n="The Western Pylon", d="Discover the location of the Western Crystal Pylon.", objs={"Western Crystal Pylon"}},
    [4289] = {n="The Apes of Un'Goro", d="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", tgo={{"Un'Goro Gorilla", "Un'Goro Gorilla"}, {"Un'Goro Stomper"}, {"Un'Goro Thunderer"}}},
    [4290] = {n="The Fare of Lar'korwi", d="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.", objs={"Fresh Threshadon Carcass"}},
    [4291] = {n="The Scent of Lar'korwi", d="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.", tgo={{"Lar'korwi Mate"}}},
    [4292] = {n="The Bait for Lar'korwi", d="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Tablet of the Seven", d="Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes.", objs={"Tablet of the Seven"}},
    [4301] = {n="The Mighty U'cha", d="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", tgo={{"U'cha"}}},
    [4321] = {n="Making Sense of It", d="Speak with J.D. Collie in a moment."},
    [4341] = {n="Kharan Mighthammer", d="Travel to Blackrock Depths and find Kharan Mighthammer.\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."},
    [4421] = {n="The Corruption of the Jadefire", d="Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.", tgo={{"Jadefire Felsworn"}, {"Jadefire Shadowstalker"}, {"Jadefire Rogue"}, {"Xavathras"}}},
    [4441] = {n="Felbound Ancients", d="Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.", objs={"Temple of the Moon Fountain"}},
    [4442] = {n="Purified!", d="Speak to Eridan again in a moment."},
    [4449] = {n="Caught!", d="Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.", tgo={{"Dark Iron Geologist"}, {}}, objs={"Alterac Granite", "Battered Chest", "Solid Chest"}},
    [4450] = {n="Ledger from Tanaris", d="Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.", tgo={{}, {"Glassweb Spider"}, {}, {"Jarquia"}}, objs={"Goodsteel Ledger", "Damaged Crate"}},
    [4491] = {n="A Little Help From My Friends", d="Lead Ringo to Spraggle Frock at Marshal's Refuge.\nIf Ringo faints, use Spraggle's Canteen to revive him."},
    [4492] = {n="Lost!", d="Find Ringo at Fire Plume Ridge."},
    [4493] = {n="March of the Silithid", d="Speak to Alchemist Pestlezugg in Gadgetzan."},
    [4495] = {n="A Good Friend", d="Find Iverron by the cave to the north."},
    [4496] = {n="Bungle in the Jungle", d="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", tgo={{"Gorishi Wasp", "Gorishi Worker", "Gorishi Reaver", "Gorishi Stinger", "Gorishi Tunneler", "Gorishi Hive Guard", "Gorishi Hive Queen"}, {}}, objs={"Un'Goro Dirt Pile"}},
    [4501] = {n="Beware of Pterrordax", d="Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge.", tgo={{"Pterrordax"}, {"Frenzied Pterrordax"}}},
    [4502] = {n="Volcanic Activity", d="Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet.", tgo={{"Scorching Elemental", "Living Blaze", "Blazerunner", "Blazing Invader", "Baron Charr"}}},
    [4503] = {n="Shizzle's Flyer", d="Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge.", tgo={{"Young Diemetradon", "Diemetradon", "Elder Diemetradon"}, {"Fledgling Pterrordax", "Pterrordax", "Frenzied Pterrordax"}}},
    [4504] = {n="Super Sticky", d="Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.", tgo={{"Tar Beast", "Tar Lurker", "Tar Lord", "Tar Creeper"}}},
    [4581] = {n="Kayneth Stillwind", d="Take Shindrell's Note to Kayneth Stillwind in Forest Song."},
    [4681] = {n="Washed Ashore", d="Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.", objs={"Skeletal Sea Turtle"}},
    [4722] = {n="Beached Sea Turtle", d="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
    [4723] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4725] = {n="Beached Sea Turtle", d="Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine."},
    [4726] = {n="Broodling Essence", d="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", objs={"Broodling Essence"}},
    [4727] = {n="Beached Sea Turtle", d="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
    [4728] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4730] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4731] = {n="Beached Sea Turtle", d="Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine."},
    [4732] = {n="Beached Sea Turtle", d="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
    [4733] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4740] = {n="WANTED: Murkdeep!", d="Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.\nReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.", tgo={{"Murkdeep"}}},
    [4761] = {n="Thundris Windweaver", d="Speak with Thundris Windweaver in Auberdine."},
    [4762] = {n="The Cliffspring River", d="Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\nReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="The Blackwood Corrupted", d="Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\nGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\nMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\nTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.", objs={"Xabraxxis' Demon Bag"}},
    [4811] = {n="The Red Crystal", d="Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range. Report back what you find to Sentinel Glynda Nal'Shea in Auberdine.", objs={"Mysterious Red Crystal"}},
    [4812] = {n="As Water Cascades", d="Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall.", objs={"Auberdine Moonwell"}},
    [4813] = {n="The Fragments Within", d="Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine."},
    [4842] = {n="Strange Sources", d="Follow Donova Snowden's instructions, then report back."},
    [4861] = {n="Enraged Wildkin", d="Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring."},
    [4863] = {n="Enraged Wildkin", d="Find Jaron Stoneshaper's wrecked wagon."},
    [4864] = {n="Enraged Wildkin", d="Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.\nBring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring.", tgo={{}, {"Crazed Owlbeast", "Moontouched Owlbeast", "Berserk Owlbeast", "Guardian of Elune"}}, objs={"Jaron's Supplies"}},
    [4901] = {n="Guardians of the Altar", d="Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village."},
    [4902] = {n="Wildkin of Elune", d="Speak with Arch Druid Fandral Staghelm in Darnassus."},
    [4906] = {n="Further Corruption", d="Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed.", tgo={{"Jadefire Hellcaller"}, {"Jadefire Betrayer"}, {"Jadefire Trickster"}, {"Xavaric"}}},
    [4971] = {n="A Matter of Time", d="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\nSlay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.", tgo={{"Temporal Parasite"}}},
    [4984] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Wolf"}}},
    [4985] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Grizzly"}}},
    [4986] = {n="Glyphed Oaken Branch", d="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance."},
    [5021] = {n="Better Late Than Never", d="The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible."},
    [5022] = {n="Better Late Than Never", d="Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone. There is usually a census officer located in City Hall."},
    [5048] = {n="Good Natured Emma", d="Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone. If she is, then perhaps she'd like the package Janice Felstone made for her."},
    [5050] = {n="Good Luck Charm", d="Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm."},
    [5066] = {n="A Call to Arms: The Plaguelands!", d="Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."},
    [5082] = {n="Threat of the Winterfall", d="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.", tgo={{"Winterfall Pathfinder"}, {"Winterfall Den Watcher"}, {"Winterfall Totemic"}}},
    [5083] = {n="Winterfall Firewater", d="Bring the Empty Firewater Flask to Donova Snowden in Winterspring."},
    [5084] = {n="Falling to Corruption", d="Search the Deadwood furbolg camp in northern Felwood for a clue."},
    [5085] = {n="Mystery Goo", d="Report back to Donova Snowden with your findings."},
    [5092] = {n="Clear the Way", d="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.\nReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", tgo={{"Skeletal Flayer"}, {"Slavering Ghoul"}}},
    [5097] = {n="All Along the Watchtowers", d="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\nOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.", tgo={{"Andorhal Tower One"}, {"Andorhal Tower Two"}, {"Andorhal Tower Three"}, {"Andorhal Tower Four"}}},
    [5149] = {n="Pamela's Doll", d="Find Pamela's doll."},
    [5152] = {n="Auntie Marlene", d="Speak with Marlene, south of the Ruins of Andorhal."},
    [5153] = {n="A Strange Historian", d="Bring Joseph's Wedding Ring to Chromie.", objs={"Joseph Redpath's Monument"}},
    [5154] = {n="The Annals of Darrowshire", d="Bring the Annals of Darrowshire to Chromie in Andorhal.", objs={"Musty Tome"}},
    [5155] = {n="Forces of Jaedenar", d="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.", tgo={{"Jaedenar Hound"}, {"Jaedenar Guardian"}, {"Jaedenar Adept"}, {"Jaedenar Cultist"}}},
    [5156] = {n="Verifying the Corruption", d="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.", tgo={{"Entropic Beast"}, {"Entropic Horror"}}},
    [5157] = {n="Collection of the Corrupt Water", d="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.", objs={"Corrupt Jaedenar Moonwell"}},
    [5158] = {n="Seeking Spiritual Aid", d="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens."},
    [5159] = {n="Cleansed Water Returns to Felwood", d="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."},
    [5168] = {n="Heroes of Darrowshire", d="Bring Davil's Libram and Redpath's Shield to Carlin Redpath.", objs={"Davil's Libram", "Redpath's Shield"}},
    [5181] = {n="Villains of Darrowshire", d="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", objs={"Horgus' Skull", "Shattered Sword of Marduk"}},
    [5210] = {n="Brother Carlin", d="Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands."},
    [5211] = {n="Defenders of Darrowshire", d="Free 15 Darrowshire Spirits and return to Carlin Redpath.", tgo={{"Darrowshire Spirit"}}},
    [5215] = {n="The Scourge Cauldrons", d="Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands."},
    [5216] = {n="Target: Felstone Field", d="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Bilemaw"}}},
    [5217] = {n="Return to Chillwind Camp", d="Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5219] = {n="Target: Dalson's Tears", d="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Malvinious"}}},
    [5220] = {n="Return to Chillwind Camp", d="Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5222] = {n="Target: Writhing Haunt", d="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Razarch"}}},
    [5223] = {n="Return to Chillwind Camp", d="Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5225] = {n="Target: Gahrron's Withering", d="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Soulwrath"}}},
    [5226] = {n="Return to Chillwind Camp", d="Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5238] = {n="Mission Accomplished!"},
    [5241] = {n="Uncle Carlin", d="Find Carlin Redpath."},
    [5244] = {n="The Ruins of Kel'Theril", d="Speak with Jaron Stoneshaper in Starfall Village."},
    [5245] = {n="Troubled Spirits of Kel'Theril", d="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.", objs={"Highborne Relic Fragment"}},
    [5246] = {n="Fragments of the Past", d="Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.", objs={"Sacred Highborne Writings"}},
    [5250] = {n="Starfall", d="Find Starfall in Winterspring and speak with Wynd Nightchaser."},
    [5261] = {n="Eagan Peltskinner", d="Speak with Eagan Peltskinner."},
    [5401] = {n="Argent Dawn Commission"},
    [5541] = {n="Ammo for Rumbleshot", d="Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.", objs={"Ammo Crate"}},
    [5542] = {n="Demon Dogs", d="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", tgo={{"Plaguehound Runt"}, {"Plaguehound"}, {"Frenzied Plaguehound"}}},
    [5543] = {n="Blood Tinged Skies", d="Slay 30 Plaguebats and return to Tirion Fordring.", tgo={{"Plaguebat"}}},
    [5544] = {n="Carrion Grubbage", d="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", tgo={{"Carrion Grub", "Carrion Devourer"}}},
    [5545] = {n="A Bundle of Trouble", d="Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.", objs={"Bundle of Wood"}},
    [5601] = {n="Sister Pamela", d="Find Pamela Redpath in Darrowshire."},
    [5713] = {n="One Shot. One Kill.", d="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."},
    [5742] = {n="Redemption", d="Listen to what Tirion Fordring has to say.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Hemet Nesingwary", d="Take Kravel's Crate to Hemet Nesingwary in Stranglethorn."},
    [5781] = {n="Of Forgotten Memories", d="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", tgo={{"Mercutio Filthgorger"}}},
    [5845] = {n="Of Lost Honor", d="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", objs={"Symbol of Lost Honor"}},
    [5846] = {n="Of Love and Family", d="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."},
    [5848] = {n="Of Love and Family", d="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\nReturn the painting to Tirion Fordring.", objs={"Unfinished Painting"}},
    [5863] = {n="The Dunemaul Compound", d="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", tgo={{"Dunemaul Brute"}, {"Dunemaul Enforcer"}, {"Gor'marok the Ravager"}}},
    [5903] = {n="A Plague Upon Thee", d="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", objs={"Large Termite Mound"}},
    [5904] = {n="A Plague Upon Thee", d="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites."},
    [6001] = {n="Body and Heart", d="Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done.", tgo={{"Lunaclaw Spirit"}}},
    [6004] = {n="Unfinished Business", d="Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.", tgo={{"Scarlet Medic"}, {"Scarlet Hunter"}, {"Scarlet Mage"}, {"Scarlet Knight"}}},
    [6021] = {n="Zaeldarr the Outcast", d="Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.", tgo={{"Zaeldarr the Outcast"}}},
    [6023] = {n="Unfinished Business", d="Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.", tgo={{"Huntsman Radley"}, {"Cavalier Durgen"}}},
    [6024] = {n="Hameya's Plea", d="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", tgo={{"Infiltrator Hameya"}}},
    [6025] = {n="Unfinished Business", d="Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands."},
