    [6030] = {n="Duke Nicholas Zverenhoff", d="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands."},
    [6063] = {n="Taming the Beast", d="Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Webwood Lurker"}}},
    [6064] = {n="Taming the Beast", d="Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", tgo={{"Large Crag Boar"}}},
    [6084] = {n="Taming the Beast", d="Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.", tgo={{"Snow Leopard"}}},
    [6085] = {n="Taming the Beast", d="Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", tgo={{"Ice Claw Bear"}}},
    [6086] = {n="Training the Beast", d="Speak with Belia Thundergranite in Ironforge."},
    [6101] = {n="Taming the Beast", d="Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Nightsaber Stalker"}}},
    [6102] = {n="Taming the Beast", d="Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Strigid Screecher"}}},
    [6103] = {n="Training the Beast", d="Speak to Jocaste in the Cenarion Enclave, in Darnassus."},
    [6134] = {n="Ghost-o-plasm Round Up", d="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", tgo={{"Magrami Spectre"}}},
    [6182] = {n="The First and the Last", d="Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks."},
    [6183] = {n="Honor the Dead", d="Speak with Mathias Shaw again if you wish to accept his task."},
    [6184] = {n="Flint Shadowmore", d="Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore."},
    [6185] = {n="The Eastern Plagues", d="Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", objs={"Mangled Human Remains"}},
    [6341] = {n="The Bounty of Teldrassil", d="Bring Nessa's Collection to Vesprystus."},
    [6342] = {n="Flight to Auberdine", d="Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird."},
    [6343] = {n="Return to Nessa", d="Bring Laird's Response to Nessa Shadowsong."},
    [6344] = {n="Nessa Shadowsong", d="Speak with Nessa Shadowsong."},
    [6387] = {n="Honor Students", d="Bring Brock's List to Thorgrum Borrelson in Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Bring the Honorary Picks to Gryth Thurden in Ironforge."},
    [6389] = {n="A Plague Upon Thee", d="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."},
    [6391] = {n="Ride to Ironforge", d="Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge."},
    [6392] = {n="Return to Brock", d="Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar."},
    [6603] = {n="Trouble in Winterspring!", d="Find Donova Snowden near the hot springs in Winterspring."},
    [6604] = {n="Enraged Wildkin", d="Speak with Jaron Stoneshaper at Starfall Village."},
    [7383] = {n="Crown of the Earth", d="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", objs={"Oracle Glade Moonwell"}},
    [7701] = {n="WANTED: Overseer Maltorius", d="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", tgo={{"Overseer Maltorius"}}},
    [7722] = {n="What the Flux?", d="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", objs={"Secret Plans: Fiery Flux"}},
    [7723] = {n="Curse These Fat Fingers", d="Hansel Heavyhands wants you to kill 20 Heavy War Golems.\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", tgo={{"Heavy War Golem"}}},
    [7724] = {n="Fiery Menace!", d="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", tgo={{"Greater Lava Spider"}}},
    [7727] = {n="Incendosaurs? Whateverosaur is More Like It", d="Hansel Heavyhands wants you to kill 20 Incendosaurs.\nYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", tgo={{"Incendosaur"}}},
    [7728] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass", d="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\nThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", tgo={{"Dark Iron Steamsmith"}, {"Dark Iron Lookout"}}},
    [7729] = {n="JOB OPPORTUNITY: Culling the Competition", d="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.", tgo={{"Dark Iron Taskmaster"}, {"Dark Iron Slaver"}}},
    [7733] = {n="Improved Quality", d="Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.", tgo={{"Rage Scar Yeti", "Elder Rage Scar", "Ferocious Rage Scar", "Lurking Feral Scar"}}},
    [7735] = {n="Pristine Yeti Hide", d="Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas."},
    [7791] = {n="A Donation of Wool", d="Use/collect: Alterac Granite, Tattered Chest, Battered Chest", objs={"Alterac Granite", "Tattered Chest", "Battered Chest"}},
    [7793] = {n="A Donation of Silk", d="Use/collect: Alterac Granite, Battered Chest, Solid Chest", objs={"Alterac Granite", "Battered Chest", "Solid Chest"}},
    [8360] = {n="Dancing for Marzipan", d="Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!", tgo={{"Innkeeper Pala"}}},
    [8365] = {n="Pirate Hats Ahoy!", d="Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.", tgo={{"Southsea Pirate", "Southsea Freebooter", "Southsea Dock Worker", "Southsea Swashbuckler", "Andre Firebeard", "Kregg Keelhaul"}}},
    [8460] = {n="Timbermaw Ally", d="Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.", tgo={{"Deadwood Warrior"}, {"Deadwood Pathfinder"}, {"Deadwood Gardener"}}},
    [8461] = {n="Deadwood of the North", d="Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", tgo={{"Deadwood Den Watcher"}, {"Deadwood Avenger"}, {"Deadwood Shaman"}}},
    [8462] = {n="Speak to Nafien", d="Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold."},
    [8464] = {n="Winterfall Activity", d="Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.", tgo={{"Winterfall Shaman"}, {"Winterfall Den Watcher"}, {"Winterfall Ursa"}}},
    [86574] = {n="Stonetalon Supply Run", d="Collect 6 Stonetalon Supplies from Pridewing Wyverns and deliver them to Innkeeper Faralia.", tgo={{"Young Pridewing", "Pridewing Wyvern", "Pridewing Skyhunter", "Pridewing Consort", "Pridewing Patriarch", "Freewind Post Wyvern"}}},
