    [91733] = {n="Downstream", d="Collect the Waterlogged Axe, Waterlogged Saw, and Waterlogged Toolbox that have washed downstream from Eastvale Logging Camp, then return to Ormin Pelford.", objs={"Waterlogged Axe", "Waterlogged Saw", "Waterlogged Toolbox"}},
    [91740] = {n="Croaky's Head", d="Deliver Croaky's Head to Merell Ross at Ridgepoint Tower."},
    [91741] = {n="Nibbled-On Book", d="Return the book to Brother Paxton."},
