    [91777] = {n="Rare Books", d="Recover \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\" and return them to Brother Paxton inside Northshire's Abbey.", tgo={{"Geosculptor Yip", "Kobold Geomancer"}, {"Mother Fang", "Kobold Geomancer"}}},
    [92124] = {n="Book Inventory", d="Speak to Daniel, Brother Paxton's assistant in the library."},
