    [92553] = {n="Restocking the Larders", d="Collect 3 Small Eggs and 8 Strider Meat from creatures found throughout the Shen'dar Highlands.", tgo={{"Greater Fleshripper", "Young Fleshripper", "Dire Condor", "Fleshripper", "Mountain Buzzard", "Strigid Owl", "Strigid Screecher", "Strigid Hunter"}, {"Strider Clutchmother", "Foreststrider Fledgling", "Foreststrider", "Giant Foreststrider", "Greater Plainstrider", "Ornery Plainstrider", "Fleeting Plainstrider", "Galestrider"}}},
    [92595] = {n="The Windshapers", d="Listen to what Illaya Amberwind has to say.", tgo={{"Illaya Amberwind"}}},
    [92598] = {n="The Gift of Skysight", d="Use your Skysight racial ability at the Elemental Convergence in Thendal Grove.", objs={"Elemental Convergence"}},
    [92640] = {n="Desperate Times", d="Speak with Valennia Stormfist in Valanaar and follow her instructions.", tgo={{"Valennia Stormfist"}, {"Ayessa Dawnsinger"}, {"Elaadrin Evengale"}}},
    [92642] = {n="Disrupting Logistics", d="Slay 4 Al'Aketh Healers and 8 Al'Aketh Brawlers in the Gustberry Lowlands.", tgo={{"Al'Aketh Healer"}, {"Al'Aketh Brawler"}}},
    [92643] = {n="The Turncoat", d="Find the cultist turncoat at the house just inside the highlands northwest of Valanaar.", tgo={{}, {"Dead Cultist"}}},
    [92644] = {n="Unfortunate News", d="Deliver the glowing crystal to Talanaanis Shadowsong in Valanaar."},
    [92645] = {n="Breaking the Breaker", d="Slay Commander Belguilos in the Gustberry Lowlands.", tgo={{"Commander Belguilos"}}},
    [92679] = {n="Blood Tithe", d="Listen to what Alvarion Windfield has to say and find Aamelia Windfield at the Windfield Orchard.", tgo={{"Aamelia Windfield"}, {"Alvarion Windfield"}}},
    [92682] = {n="Make Yourself Useful", d="Gather 10 Ripe Stormapples and slay 5 Hungry Bandits at the Windfield Orchard.", tgo={{"Hungry Bandit"}, {}}, objs={"Ripe Stormapple"}},
    [92683] = {n="Flutterfly Dust", d="Gather 5 Flutterfly Dust from the Flutterflies around the Gustberry Lowlands.", objs={"Flutterfly Dust"}},
    [92684] = {n="Ornery Ornery Galestriders", d="Gather 7 Lowlands Galestrider Tenderloins from the Ornery Galestriders found throughout the Gustberry Lowlands.", tgo={{"Ornery Galestrider"}}},
    [92685] = {n="The Hills Have Eyes", d="Loot 7 Blood-Stained Bandit Masks from Highwayman Bandits in the Gustberry Lowlands.", tgo={{"Bandit Highwayman"}}},
    [92693] = {n="Standing Our Ground", d="Speak with Aamelia Windfield when you are ready to confront the bandit leader.", tgo={{"Aamelia Windfield"}, {"Ferauu the Bludgeon"}}},
    [92698] = {n="What Is My Purpose?", d="Speak with Aamelia Windfield about the Malfunctioning Cyclone Construct."},
    [92699] = {n="The Supreme Magister", d="Find Elaadrin Evengale in Valanaar."},
    [92701] = {n="To Valanaar", d="Deliver Aonda's Written Report to Valennia Stormfist in Valanaar."},
    [92703] = {n="Deliver the News", d="Speak with Alvarion Windfield in Valanaar."},
    [92709] = {n="A Grand Adventure", d="Listen to what Elaadrin Evengale in Valanaar has to say.", tgo={{"Elaadrin Evengale"}}},
