    [92744] = {n="Murloc Gills", d="Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall.", tgo={{"Murloc Coastrunner", "Murloc Tidehunter", "Murloc Warrior", "Murloc Minor Oracle", "Murloc Hunter", "Murloc Netter", "Murloc Raider", "Murloc Oracle"}}},
